import { getUserNotificationPreference } from './db';
import { toggleNotifications } from './actions';

export default async function Page() {
  const notificationsEnabled = await getUserNotificationPreference();

  return (
    <main style={{ padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Notification Settings</h1>

      <div style={{ 
        padding: '20px', 
        border: '1px solid #ccc', 
        borderRadius: '8px',
        maxWidth: '400px'
      }}>
        <p>
          Current status: 
          <strong style={{ marginLeft: '8px', color: notificationsEnabled ? 'green' : 'red' }}>
            {notificationsEnabled ? 'ON' : 'OFF'}
          </strong>
        </p>

        <form action={toggleNotifications}>
          <button 
            type="submit"
            style={{
              padding: '10px 20px',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '16px'
            }}
          >
            Toggle Notifications
          </button>
        </form>
      </div>
    </main>
  );
}

